use vstd::prelude::*;

verus! {

    // Concatenate two vectors of u64, each of length at most 100.
    // The result has length a.len() + b.len(), and
    //   for 0 <= i < a.len(): res[i] == a[i]
    //   for a.len() <= i < res.len(): res[i] == b[i - a.len()]
    fn concat(a: &Vec<u64>, b: &Vec<u64>) -> (res: Vec<u64>)
        requires
            a.len() <= 100,
            b.len() <= 100,
        ensures
            res.len() == a.len() + b.len(),
        ensures
            forall |i: usize| i < a.len() ==> res[i] == a[i],
        ensures
            forall |i: usize| a.len() <= i && i < res.len() ==> res[i] == b[i - a.len()],
    {
        let mut res: Vec<u64> = Vec::new();
        // First, push all elements of a
        let mut i: usize = 0;
        while i < a.len()
            invariant
                i <= a.len(),
                res.len() == i,
                forall |j: usize| j < i ==> res[j] == a[j],
            decreases
                a.len() - i,
        {
            res.push(a[i]);
            i += 1;
        }

        // Next, push all elements of b
        let mut j: usize = 0;
        while j < b.len()
            invariant
                j <= b.len(),
                res.len() == a.len() + j,
                // the former prefix from `a` is still correct
                forall |k: usize| k < a.len() ==> res[k] == a[k],
                // the suffix from `b` built so far is correct
                forall |k: usize| a.len() <= k && k < a.len() + j
                               ==> res[k] == b[k - a.len()],
            decreases
                b.len() - j,
        {
            res.push(b[j]);
            j += 1;
        }

        res
    }

} // verus!

